starter:
def first_difference(live,sim):
    # TODO: scan sorted union of ticks
    return None

solution:
def first_difference(live,sim):
    for t in sorted(set(live)|set(sim)):
        if t not in live or t not in sim or sorted(live[t])!=sorted(sim[t]): return t
    return None

starter:
def coverage(live,sim):
    # TODO: separate missing and compared
    return {}

solution:
def coverage(live,sim):
    shared=set(live)&set(sim)
    return {'compared':len(shared),'exact':sum(live[t]==sim[t] for t in shared),'missing':len(set(live)^set(sim))}

starter:
def mixed(observed,before,after):
    # TODO: require a mixture, not a whole-frame shift
    return False

solution:
def mixed(observed,before,after):
    triples=list(zip(observed,before,after))
    return all(o==b or o==a for o,b,a in triples) and any(o==b and o!=a for o,b,a in triples) and any(o==a and o!=b for o,b,a in triples)
